/bin/bash -lc "Rscript - <<'RS'
link<-read.delim('https://rest.kegg.jp/link/pathway/pau',header=FALSE,col.names=c('gene','pathway'),quote='',comment.char=''); link"'$gene<-sub('"'"'^pau:'"','',link"'$gene); link$pathway<-sub('"'"'^path:pau'"','',link"'$pathway); path<-read.delim('"'https://rest.kegg.jp/list/pathway/pau',header=FALSE,col.names=c('pathway','name'),quote='',comment.char='');path"'$pathway<-sub('"'"'^pau'"','',path"'$pathway);path$name<-sub('"' - Pseudomonas aeruginosa.*"'$'"','',path"'$name);sets<-lapply(split(link$gene,link$pathway),unique)
files<-list(iron='"'/workspace/inputs/res_GluFevsGluFePlus.rds',innate='/workspace/inputs/res_SuccvsGluFePlus.rds')
res<-lapply(files,function(f){x<-readRDS(f);d<-x@listData;g<-attr(x,'rownames',exact=TRUE);list(u=g,s=g[abs(d"'$log2FoldChange)>1.5&d$padj<.05])})
for (mode in c('"'kegg','tested','mapped')) for (size in c('all','min10max500')) {
 cat('\\n',mode,size,'\\n')
 tabs<-list()
 for(nm in names(res)) {U<-if(mode=='kegg')unique(link"'$gene) else res[[nm]]$u; if(mode=='"'mapped')U<-intersect(U,unique(link"'$gene));S<-intersect(res[[nm]]$s,U); ss<-lapply(sets,intersect,y=U); sz<-vapply(ss,length,integer(1));keep<-if(size=='"'all')sz>0 else sz>=10&sz<=500;ss<-ss[keep];N<-length(U);n<-length(S);p<-vapply(ss,function(g)phyper(sum(S%in%g)-1,length(g),N-length(g),n,lower.tail=FALSE),numeric(1));q<-p.adjust(p,'BH');tabs[[nm]]<-data.frame(id=names(ss),p=p,q=q,M=sz[keep],k=vapply(ss,function(g)sum(S%in%g),integer(1)))}
 for(nm in names(tabs)){z<-tabs[[nm]];cat(nm,'npath',nrow(z),'sig',sum(z"'$q<.05),'"'\\n');print(z[z"'$q<.08,order(z$q),drop=FALSE],row.names=FALSE)}
 a<-tabs[[1]]$id[tabs[[1]]$q<.05];b<-tabs[[2]]$id[tabs[[2]]$q<.05];cat('"'diff',paste(setdiff(a,b),collapse=','),'count',length(setdiff(a,b)),'\\n')
}
RS"

